// Normalise the feed items, drop duplicates and anything older than max_age_days.
const cfg = $('Config').first().json;
const maxAgeMs = cfg.max_age_days * 24 * 60 * 60 * 1000;
const now = Date.now();

const text = (value) =>
  String(value || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#39;|&rsquo;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/\s+/g, ' ')
    .trim();

// Cheap filter before any AI call: keep offers whose title or text mentions a keyword.
const keywords = (cfg.keywords || []).map((k) => String(k).toLowerCase());
const matches = (s) => !keywords.length || keywords.some((k) => new RegExp(`\\b${k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`).test(s));

const seen = new Set();
const offers = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.link || j.error) continue; // a feed that failed returns an error item: skip it
  const link = String(j.link).split('?')[0].split('#')[0];
  if (seen.has(link)) continue;
  const published = new Date(j.isoDate || j.pubDate || now);
  if (Number.isNaN(published.getTime()) || now - published.getTime() > maxAgeMs) continue;
  const body = text(j['content:encoded'] || j.content || j.contentSnippet || j.description);
  if (!matches(`${text(j.title)} ${body}`.toLowerCase())) continue;
  seen.add(link);
  const host = link.match(/^https?:\/\/([^/:]+)/i);
  const source = host ? host[1].replace(/^www\./, '') : 'unknown';
  offers.push({
    json: {
      link,
      title: text(j.title).slice(0, 200),
      source,
      published_at: published.toISOString(),
      description: body.slice(0, 4000),
    },
  });
}
return offers;

// Protect the free Gemini quota: score at most max_offers_per_run new offers per run.
// The rest stay unseen and are picked up by the next run.
const cfg = $('Config').first().json;
return $input.all().slice(0, cfg.max_offers_per_run);

// Build the Gemini request. The answer must follow a JSON schema, so it can be checked.
const cfg = $('Config').first().json;
const offer = $json;

const prompt = [
  'You screen remote job offers for one freelance engineer.',
  '',
  'CANDIDATE CRITERIA',
  cfg.criteria,
  '',
  'OFFER',
  `Title: ${offer.title}`,
  `Source: ${offer.source}`,
  `Link: ${offer.link}`,
  'Description:',
  offer.description,
  '',
  'Score the offer from 0 to 100 against the criteria.',
  'Rules: be strict; missing information is a risk, not a plus; use only facts written in the offer;',
  'verdict is "apply" (70 or more), "discuss" (50 to 69) or "skip" (below 50);',
  'reasons: two or three sentences quoting the facts you used.',
].join('\n');

return {
  json: {
    ...offer,
    request: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: 0.2,
        responseMimeType: 'application/json',
        responseSchema: {
          type: 'OBJECT',
          properties: {
            score: { type: 'INTEGER' },
            verdict: { type: 'STRING', enum: ['apply', 'discuss', 'skip'] },
            reasons: { type: 'STRING' },
            english_risk: { type: 'STRING', enum: ['low', 'medium', 'high'] },
            red_flags: { type: 'ARRAY', items: { type: 'STRING' } },
          },
          required: ['score', 'verdict', 'reasons', 'english_risk', 'red_flags'],
        },
      },
    },
  },
};

// Guardrail: never trust the AI answer blindly. A failed call is stored as "error", a
// malformed or inconsistent answer as "invalid"; both are flagged for a manual look.
const cfg = $('Config').first().json;
const offer = $('Build the Gemini request').item.json;

const problems = [];
let ai = null;
if ($json.error) {
  // The call itself failed (quota, network, wrong key...). Keep the offer, flagged.
  const err = $json.error;
  problems.push(`Gemini call failed: ${String(err.message || err.description || JSON.stringify(err)).slice(0, 300)}`);
} else {
  try {
    ai = JSON.parse($json.candidates[0].content.parts[0].text);
  } catch (e) {
    problems.push('the answer is not valid JSON');
  }
  if (!problems.length && (ai === null || typeof ai !== 'object' || Array.isArray(ai))) {
    problems.push('the answer is not a JSON object');
    ai = null;
  }
}
if (ai) {
  if (!Number.isInteger(ai.score) || ai.score < 0 || ai.score > 100) problems.push('score outside 0-100');
  if (!['apply', 'discuss', 'skip'].includes(ai.verdict)) problems.push('unknown verdict');
  // Same bands as in the prompt: apply 70+, discuss 50-69, skip below 50.
  const band = ai.score >= 70 ? 'apply' : ai.score >= 50 ? 'discuss' : 'skip';
  if (Number.isInteger(ai.score) && ['apply', 'discuss', 'skip'].includes(ai.verdict) && ai.verdict !== band) {
    problems.push(`"${ai.verdict}" does not match a score of ${ai.score}`);
  }
  if (!['low', 'medium', 'high'].includes(ai.english_risk)) problems.push('unknown english_risk');
  if (!Array.isArray(ai.red_flags)) problems.push('red_flags is not a list');
  if (!ai.reasons || String(ai.reasons).trim().length < 20) problems.push('no real justification');
}
const valid = problems.length === 0;
const failed = Boolean($json.error);

return {
  json: {
    link: offer.link,
    title: offer.title,
    source: offer.source,
    published_at: offer.published_at,
    ai_score: valid ? ai.score : null,
    ai_verdict: valid ? ai.verdict : failed ? 'error' : 'invalid',
    ai_reasons: valid ? String(ai.reasons).slice(0, 1000) : failed ? problems[0] : `AI answer rejected: ${problems.join('; ')}`,
    english_risk: valid ? ai.english_risk : '',
    red_flags: valid ? ai.red_flags.map(String).join(' | ').slice(0, 500) : '',
    model: cfg.model,
    status: 'to_review',
    human_decision: '',
    decided_at: '',
  },
};

// One Telegram message listing today's new offers, best first.
// Sent to Telegram as HTML: escape every text that comes from a feed or from the AI.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => (s.length > n ? `${s.slice(0, n).replace(/\s+\S*$/, '')}…` : s);

const offers = $input.all().map((i) => i.json).filter((o) => o.link);
if (offers.length === 0) return [];

const ranked = offers
  .filter((o) => o.ai_score !== null && o.ai_score !== undefined && o.ai_score !== '')
  .sort((a, b) => b.ai_score - a.ai_score);
const flagged = offers.filter((o) => o.ai_verdict === 'invalid' || o.ai_verdict === 'error');

const lines = [
  `<b>Job offers: ${offers.length} new</b>`,
  'AI ranking only. Nothing is applied automatically: decide in the job_offers table (human_decision = apply or skip).',
  '',
];
for (const o of ranked) {
  lines.push(`<b>${o.ai_score} · ${o.ai_verdict}</b> · ${esc(o.title)}`);
  lines.push(`   ${esc(o.source)} · English risk: ${esc(o.english_risk || '?')}`);
  if (o.red_flags) lines.push(`   ⚠️ ${esc(o.red_flags)}`);
  lines.push(`   ${esc(cut(String(o.ai_reasons), 300))}`);
  lines.push(`   ${esc(o.link)}`);
  lines.push('');
}
if (flagged.length) {
  lines.push(`⚠️ ${flagged.length} offer(s) need a manual look (AI answer rejected or failed):`);
  for (const o of flagged) lines.push(`- ${esc(o.title)} — ${esc(o.link)}`);
}

let text = lines.join('\n');
if (text.length > 3900) {
  // Cut between lines so no HTML tag is left open.
  text = `${text.slice(0, 3850).replace(/\n[^\n]*$/, '')}\n… (truncated, see the table)`;
}
return [{ json: { text } }];
